package io.neo.omnitrix;

import android.app.*;import android.content.*;import android.graphics.Color;import android.os.Bundle;import android.view.*;import android.widget.*;import org.json.JSONObject;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;

/** Omnitrix v2.6 authenticated external miner adapter controller. */
public class MinerControlActivity extends Activity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private SharedPreferences prefs;private EditText endpoint,token;private TextView state,hash,temp,power,status;private Button refresh,start,stop;
 @Override public void onCreate(Bundle s){super.onCreate(s);getWindow().setStatusBarColor(Color.BLACK);getWindow().setNavigationBarColor(Color.BLACK);prefs=getSharedPreferences("omnitrix_miner",MODE_PRIVATE);buildUi();}
 private void buildUi(){LinearLayout shell=new LinearLayout(this);shell.setOrientation(LinearLayout.VERTICAL);shell.setBackgroundColor(Color.rgb(1,5,3));ScrollView scroll=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(22),dp(18),dp(20));scroll.addView(root);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.omnitrix_logo);head.addView(logo,new LinearLayout.LayoutParams(dp(68),dp(68)));head.addView(text("  NEO MINER",25,Color.rgb(228,255,235)));root.addView(head);TextView sub=text("Omnitrix v2.6 · authenticated external miner adapter",12,Color.rgb(104,185,130));sub.setPadding(0,dp(5),0,dp(16));root.addView(sub);endpoint=input("https://miner-adapter.example");endpoint.setText(prefs.getString("endpoint",""));token=input("Adapter access token");token.setInputType(0x00000081);token.setText(prefs.getString("token",""));root.addView(endpoint,new LinearLayout.LayoutParams(-1,dp(52)));LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(-1,dp(52));tp.setMargins(0,dp(8),0,0);root.addView(token,tp);Button save=secondary("SAVE ADAPTER");root.addView(save,new LinearLayout.LayoutParams(-1,dp(48)));save.setOnClickListener(v->{String e=endpoint.getText().toString().trim();if(!e.startsWith("https://")){status.setText("Only authenticated HTTPS miner adapters are allowed.");return;}prefs.edit().putString("endpoint",trim(e)).putString("token",token.getText().toString()).apply();status.setText("Adapter saved locally on this device.");});state=card("STATUS\nNot connected");hash=card("HASHRATE\n—");temp=card("TEMPERATURE\n—");power=card("POWER\n—");root.addView(state);root.addView(hash);root.addView(temp);root.addView(power);LinearLayout actions=new LinearLayout(this);refresh=primary("REFRESH");start=primary("START");stop=secondary("STOP");actions.addView(refresh,new LinearLayout.LayoutParams(0,dp(52),1f));actions.addView(start,new LinearLayout.LayoutParams(0,dp(52),1f));actions.addView(stop,new LinearLayout.LayoutParams(0,dp(52),1f));root.addView(actions);refresh.setOnClickListener(v->call("GET","/v1/status"));start.setOnClickListener(v->confirm("Start mining on this authenticated external adapter?",()->call("POST","/v1/start")));stop.setOnClickListener(v->confirm("Stop mining on this authenticated external adapter?",()->call("POST","/v1/stop")));status=text("Configure a compatible NEO Miner adapter you control. Omnitrix does not claim the phone itself is performing ASIC mining.",12,Color.rgb(181,214,191));status.setPadding(0,dp(16),0,0);root.addView(status);shell.addView(scroll,new LinearLayout.LayoutParams(-1,0,1f));shell.addView(OmnitrixNav.bar(this,"Miner"),new LinearLayout.LayoutParams(-1,dp(54)));setContentView(shell);}
 private void call(String method,String path){String base=trim(endpoint.getText().toString().trim());String t=token.getText().toString();if(!base.startsWith("https://")){status.setText("Enter an HTTPS adapter endpoint first.");return;}refresh.setEnabled(false);status.setText("Contacting authenticated miner adapter…");io.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(base+path).openConnection();c.setRequestMethod(method);c.setConnectTimeout(12000);c.setReadTimeout(12000);c.setRequestProperty("Accept","application/json");if(!t.isEmpty())c.setRequestProperty("Authorization","Bearer "+t);if("POST".equals(method)){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream o=c.getOutputStream()){o.write("{}".getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();String body=read(in);if(code<200||code>=300)throw new IOException("HTTP "+code);JSONObject j=new JSONObject(body);runOnUiThread(()->render(j));}catch(Exception e){runOnUiThread(()->{refresh.setEnabled(true);status.setText("Adapter unavailable: "+safe(e));});}});}
 private void render(JSONObject j){refresh.setEnabled(true);JSONObject d=j.optJSONObject("data");if(d==null)d=j;state.setText("STATUS\n"+d.optString("status",d.optBoolean("mining",false)?"Mining":"Connected"));hash.setText("HASHRATE\n"+value(d,"hashrate","hashrate_ths","—"));temp.setText("TEMPERATURE\n"+value(d,"temperature","temperature_c","—"));power.setText("POWER\n"+value(d,"power","power_w","—"));status.setText("Live miner telemetry received from authenticated adapter.");}
 private String value(JSONObject d,String a,String b,String f){Object v=d.opt(a);if(v==null)v=d.opt(b);return v==null?f:String.valueOf(v);}private void confirm(String m,Runnable r){new AlertDialog.Builder(this).setTitle("NEO Miner").setMessage(m).setPositiveButton("Confirm",(d,w)->r.run()).setNegativeButton("Cancel",null).show();}private String read(InputStream in)throws Exception{if(in==null)return"{}";try(BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){StringBuilder b=new StringBuilder();String s;while((s=r.readLine())!=null)b.append(s);return b.toString();}}private String trim(String s){while(s.endsWith("/"))s=s.substring(0,s.length()-1);return s;}private EditText input(String h){EditText e=new EditText(this);e.setHint(h);e.setSingleLine(true);e.setTextColor(Color.WHITE);e.setHintTextColor(Color.rgb(95,125,105));e.setBackgroundColor(Color.rgb(5,20,12));e.setPadding(dp(12),0,dp(12),0);return e;}private TextView card(String s){TextView t=text(s,18,Color.rgb(220,255,230));t.setPadding(dp(16),dp(14),dp(16),dp(14));t.setBackgroundColor(Color.rgb(5,20,12));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(82));lp.setMargins(0,dp(8),0,0);t.setLayoutParams(lp);return t;}private TextView text(String s,float z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);return t;}private Button primary(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.rgb(0,22,8));b.setBackgroundColor(Color.rgb(101,255,138));return b;}private Button secondary(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.rgb(188,235,201));b.setBackgroundColor(Color.rgb(7,25,15));return b;}private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}private String safe(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}@Override protected void onDestroy(){io.shutdownNow();super.onDestroy();}
}
